        'important_terms' => [
            ['term' => 'Cognitive Behavioral Therapy for Insomnia (CBT-I)', 'definition' => 'A structured psychological therapy combining stimulus control, sleep restriction, sleep hygiene, and cognitive restructuring for chronic insomnia.'],
            ['term' => 'Sleep Restriction Therapy', 'definition' => 'A behavioral CBT-I component that temporarily limits time in bed to match actual sleep time, consolidating sleep and increasing homeostatic sleep drive.'],
            ['term' => 'Stimulus Control', 'definition' => 'A set of behavioral instructions designed to re-associate the bed and bedroom with sleep rather than wakefulness, frustration, and worry.'],
            ['term' => 'Wake After Sleep Onset (WASO)', 'definition' => 'The total duration of time an individual spends awake throughout the night after initial sleep onset has occurred.']
