        'important_terms' => [
            ['term' => 'Sleep Terrors (Pavor Nocturnus)', 'definition' => 'A NREM parasomnia characterized by abrupt awakening with a panicky scream, intense autonomic arousal, and complete amnesia.'],
            ['term' => 'Nightmare Disorder', 'definition' => 'A REM parasomnia characterized by recurrent extended, extremely dysphoric dreams that leave the individual rapidly alert upon awakening.'],
            ['term' => 'REM Sleep Behavior Disorder (RBD)', 'definition' => 'A parasomnia characterized by abnormal vocalizations and complex motor behaviors during REM sleep resulting from loss of normal muscle atonia.'],
            ['term' => 'Sexsomnia', 'definition' => 'A clinical specifier of sleepwalking involving complex sexual behaviors (masturbation, sexual vocalizations, intercourse attempts) executed while asleep.']
